ToggleItem = {}

function ToggleItem:New(o,pageGameObject)
    local o = o or { pageGameObject = nil, transform = nil };
    setmetatable(o, self);
    self.__index = self;
    self.isSelected = false;
    self.event_selected_changed = LuaDelegate:New();
    if (pageGameObject) then
        o:Init(pageGameObject);
    end
    return o;
end

function ToggleItem:Init(pageGameObject)
    self.pageGameObject = pageGameObject.gameObject;
    self.transform = pageGameObject.transform;

    self.selectedIcon = self.transform:Find("Selected").gameObject;
    self.unSelectedIcon = self.transform:Find("UnSelected").gameObject;
    self.button = self.pageGameObject:GetComponent("UIEventTrigger");
    EventDelegate.Add(self.button.onClick, EventDelegate.Callback(self.ButtonItemOnClick, self));

    self.isSelected = false;
end

function ToggleItem:SetToggleValue(selected)
    self.isSelected = selected;
    self:RefreshUI();
end

function ToggleItem:RefreshUI()
    self.selectedIcon:SetActive(self.isSelected);
end

function ToggleItem:ButtonItemOnClick()
    self.isSelected = not self.isSelected;
    self.event_selected_changed(self.isSelected);
    self:RefreshUI();
end

function ToggleItem:AddSelectedEvent(event)
    if(self.event_selected_changed ~= nil) then
        self.event_selected_changed = self.event_selected_changed + event;
    else
        self.event_selected_changed = LuaDelegate:New();
        self.event_selected_changed = event;
    end
end